parse_log <- function(lines) {
  if (length(lines) == 0) return(list(counts = integer(0), errors = character(0)))
  parts <- strsplit(lines, " ", fixed = TRUE)
  level <- sapply(parts, function(p) p[3])
  message <- sapply(parts, function(p) paste(p[4:length(p)], collapse = " "))
  counts <- table(level)
  list(counts = setNames(as.integer(counts), names(counts)), errors = unname(message[level == "ERROR"]))
}
